from collections import deque

def find_odd_moves(l):
    odd_moves = 0
    for num in l:
        if num % 2 != 0:
            odd_moves += 1
    return odd_moves

def solve(n, q):
    last_hooks = deque()
    coats = [0] * (q + 1)

    for i in range(q):
        edge = last_hooks.popleft()
        edge = next((i for i, (l, u) in enumerate(edges) if l in edge and u in edge[edge if edge] or u in edge and l in edge[edge] or edge[edge-1] == u or edge[edge+1] == l), None)
        if i - edge % 2 > 0:
            coats[edge] -= find_odd_moves(edge)
        edges.append((edge, i + 1))
        last_hooks.append((edge, i + 1))

    print(*coat for hook, coat in enumerate(coats, 1) if hook <= n)

if __name__ == "__main__":
    n, q = map(int, input().split())
    solve(n, q)
