import sys

def is_counter_clockwise(p1, p2, p3):
    return (p2[0] - p1[0]) * (p3[1] - p1[1]) - (p2[1] - p1[1]) * (p3[0] - p1[0]) > 0

def cross_product(p1, p2):
    return p1[0] * p2[1] - p2[0] * p1[1]

def side_of_triangle(p, triangle):
    a, b, c = triangle
    return cross_product(p, b) * cross_product(p, c) <= 0

def is_point_in_triangle(p, triangle):
    a, b, c = triangle
    A = (p[0] - a[0]) * (b[1] - a[1]) - (b[0] - a[0]) * (p[1] - a[1])
    B = (p[0] - b[0]) * (c[1] - b[1]) - (c[0] - b[0]) * (p[1] - b[1])
    C = (p[0] - c[0]) * (a[1] - c[1]) - (a[0] - c[0]) * (p[1] - c[1])
    return A > 0 and B > 0 and C > 0

def counting_triangles(polygon):
    n = len(polygon)
    triangles = []

    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                triangle = [polygon[i], polygon[j], polygon[k]]
                if is_counter_clockwise(polygon[0], triangle[0], triangle[-1]) and len(set(polygon[:i] + polygon[i+1:])) == n - 3:
                    triangles.append(triangle)

    return triangles

def main():
    polygon = []
    n = int(sys.stdin.readline().strip())
    for i in range(n):
        x, y = map(int, sys.stdin.readline().strip().split())
        polygon.append((x, y))

    triangles = counting_triangles(polygon)
    count = 0

    for triangle in triangles:
        if all(is_point_in_triangle(p, triangle) for p in polygon) and all(side_of_triangle(p, triangle) for p in [polygon[0], polygon[-1]]) and all(all(side_of_triangle(p, polygon[i]) == side_of_triangle(p, polygon[i+1]) for p in triangle[i+2:]) for i in range(n)):
            count += 1

    print(count % (10**9 + 7))

if __name__ == "__main__":
    main()
