import sys

def build_tree(edges):
    tree = [[] for _ in range(len(edges) + 1)]
    for u, v, x in edges:
        tree[u].append((v, x))
        tree[v].append((u, x))
    return tree

def calculate_broom_size(broom, symbol):
    path = ['']
    symbol_set = {symbol}
    for i in range(1, len(broom) + 1):
        current_symbol_set = set()
        to_remove = {}
        for parent, child, cur_symbol in broom:
            if i <= parent:
                path.append(cur_symbol)
                current_symbol_set.add(cur_symbol)
                if cur_symbol in symbol_set:
                    path.pop()
                    break
        symbol_set |= current_symbol_set
        for parent, child, cur_symbol in broom:
            if i <= parent:
                if child not in symbol_set:
                    to_remove[child] = cur_symbol
    return len(symbol_set)

def find_best_p(edges):
    broom_tree = build_tree(edges)
    min_size = float('inf')
    best_p = float('inf')
    for p in range(1, len(broom_tree) + 1):
        for i in range(1, len(broom_tree)):
            if i + p <= len(broom_tree):
                if calculate_broom_size(broom_tree, p) < min_size:
                    min_size = calculate_broom_size(broom_tree, p)
                    best_p = p
    return min_size, best_p

