    def get_min_range(nodes):
        nearest_2 = [(65536, 2 ** 20)]  # Initialize the heap with very low values
        for node in nodes:
            if not graph[node]:
                nearest_2[0] = (a[node], closest(node - 1, nodes, graph))
        heapq.heappush(heapq.heapify(nearest_2), nearest_2[0])

        result = 0
        while k > 1:
            min_value, node = heapq.heappop(heapq.heapify(nearest_2))
            result = min_value
            k -= 1
            if graph[node]:
                for neighbor in graph[node]:
                    if graph[node][-1] == neighbor:
                        continue
                    if len(graph[neighbor]) < 2:
                        if nearest_2[1][1] < (graph[neighbor][-1] - 1, graph[neighbor][-1]) < nearest_2[1][0]:
                            closest_value = nearest_2[1][0] - (graph[neighbor][-1] - 1)
                            nearest_2[1] = (graph[neighbor][-1], node)
                            heapq.heappush(heapq.heapify(nearest_2), (graph[neighbor][-1], node))
