                        else:
                            closest_value = (graph[neighbor][-1], neighbor)
                            nearest_2[1] = (graph[neighbor][-1], neighbor)
                            heapq.heappush(heapq.heapify(nearest_2), (graph[neighbor][-1], neighbor))
                    result = min(result, min_value + closest_value)
