def find_median(n, s, k, m, mlast):
    nlist = [x + i * (i + 2) for i in range(n)]

    while nlist[0] < min(m, mlast):
        if (n - (k - 1)) % 2 == 1:
            nlist = [x + i * (i + 1) for i in range(n)]
        nlist = [x + i % (k - 1) * i for i in range(n)]
        nlist.sort()
        nlist = [x * (k - 1) for x in nlist]

    while nlist[0] < min(m, mlast):
        for i in range(n - 1, -1, -1):
            if nlist[i] == s:
                nlist = [x for x in nlist if x > s]
                break

    if len(nlist) <= 1:
        return -1
    else:
        return ' '.join(map(str, nlist[:1]))

