import heapq

def dijkstra(graph, start):
    distances = {vertex: float('infinity') for vertex in graph}
    distances[start] = 0
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, current_vertex = heapq.heappop(priority_queue)

        if current_distance > distances[current_vertex]:
            continue

        for neighbor, weight in graph[current_vertex].items():
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return distances

def shortest_distances(graph, queries):
    shortest_distances = {query[0]: {"u": float('infinity'), "v": float('infinity')} for query in queries}

    result = []

    while shortest_distances:
        min_distance = float('infinity')
        closest_vertex = None
        for vertex in shortest_distances:
            if vertex.u == float('infinity') and vertex.v == float('infinity'):
                if shortest_distances[vertex][0] < min_distance:
                    min_distance = shortest_distances[vertex][0]
                    closest_vertex = vertex
                continue

            if shortest_distances[vertex][0] < min_distance and vertex.u != float('infinity') and vertex.v != float('infinity'):
                min_distance = shortest_distances[vertex][0]
                closest_vertex = vertex

            if vertex.u != float('infinity') and vertex.v == float('infinity'):
                if shortest_distances[vertex][1] < min_distance:
                    min_distance = shortest_distances[vertex][1]
                    closest_vertex = vertex
                continue

            if vertex.u != float('infinity') and vertex.v != float('infinity'):
                shortest_distances[vertex] = (min_distance, shortest_distances[vertex][1])

        u, v = min(shortest_distances.keys(), key=lambda x: shortest_distances[x][0] + shortest_distances[x][1])
        result.append(min(shortest_distances[u][0], shortest_distances[v][0]))

    return result

