import heapq

def find_max_grade(n, k, balls, connections):
    # Build the graph and its different versions
    graph = defaultdict(list)
    for u, v in connections:
        graph[u].append(v)
        graph[v].append(u)

    # Build a graph where each node is a set representing its level of neighbors
    level_graph = [[] for _ in range(n + 1)]
    for i in range(1, n + 1):
        level_graph[i].append((i, 0))

    for u, v in connections:
        for level in range(1, 4):
            if level_graph[u][0][1] == level - 1:
                level_graph[u].append((v, level))
            if level_graph[v][0][1] == level - 1:
                level_graph[v].append((u, level))

    # Function to find the maximum grade Jacob can get starting from a given root
    def dfs(node, root):
        neighbors = defaultdict(int)
        level = 0
        current_level_neighbors = []
        stack = [(node, level)]
        seen = set()

        while stack:
            u, level = stack.pop()

            if u in seen and level == level_graph[u][0][1]:
                for v, _ in current_level_neighbors:
                    neighbors[v] += balls[v]

            seen.add(u)
            current_level_neighbors.append((u, level))

            if u in connections:
                next_level_neighbors = []
                for v in graph[u]:
                    next_level_neighbors.append((v, level + 1))
                if len(next_level_neighbors) == 2:
                    val = balls[u] * min(balls[v] for v, _ in next_level_neighbors)
                    prev_val = val
                    for v, _ in current_level_neighbors:
                        prev_val += balls[v]
                        if prev_val == val:
                            return prev_val - (level << 1)
                        heapq.heappush(level_graph[v], (-previous, val, v))
            if len(current_level_neighbors) == k:
                break

            if level_graph[u][0][1] == level:
                stack.extend(next_level_neighbors)

        for v, level in current_level_neighbors:
            while current_level_neighbors and current_level_neighbors[-1][1] == level - 1:
                val = balls[v] * min(balls[x] for x in level_graph[v])
                seen.update(level_graph[v])
                level_graph[v] = []
                heapq.heappush(level_graph[v], (-x, val, x) for x in seen)
                stack.append((v, level - 1))

        prev_val = val
        for v, _ in current_level_neighbors:
            prev_val += balls[v]
            if prev_val == val:
                return prev_val - (level << 1)
            heapq.heappush(level_graph[v], (-x, val, v) for x in seen)

        return prev_val - (level << 1)

    # Find the best root
    max_grade = 0
    for u in range(1, n + 1):
        max_grade = max(dfs(u, u), max_grade)
    return max_grade

