from collections import defaultdict

def isSimpleNAV(poly):
    points = sorted(list(map(lambda x: (x[0] ** 2 + x[1] ** 2), poly)))
    for i in range(len(points) - 1):
        x0, y0 = points[i]
        x1, y1 = points[i + 1]
        if y0 * (x1 - x0) == y1 * (x0 - x0):
            return False
    return True

def solve_simple_nav_polygons(polygons, n):
    visited = [False] * n
    sides = defaultdict(list)

    for index, polygon in enumerate(polygons):
        if not isSimpleNAV(polygon):
            continue

        for i in range(n):
            x0, y0 = polygon[i]
            x1, y1 = polygon[(i + 1) % n]
            if x0 == x1 or y0 == y1:
                continue

            for j in range(i + 1, n):
                x0, y0 = polygon[i]
                x1, y1 = polygon[j]
                p0, p1 = x0 * x1 + y0 * y1, x0 * y1 - x1 * y0
                if not (x0 * p1 > 0 < x1 * p1 or y0 * p1 < 0 > y1 * p1):
                    continue
                sides[list(polygon[i:j + 1])].append((i, j))
                break

    acc = [0] * (1 << n)
    acc_zero = [0] * (1 << n)
    def num_triangles(index, used):
        if index == n:
            return 1

        add = functools.lru_cache(maxsize=1024, typed=False)(lambda: acc_zero[(1 << index) | used])
        for i in range(n):
            if visited[i] or not sides.get(polygon[i:i + len(used)]):
                continue
            for j in sides.get(polygon[i:i + len(used)]):
                if (1 << j[0]) & used or (1 << j[1]) & used:
                    continue
                used |= (1 << j[0]) | (1 << j[1])
                acc[used] += add
                visited[i] = True
                visited[j[0]] = True
                visited[j[1]] = True
                acc_zero[used] += solve_simple_nav_polygons(polygons, len(used))
                visited[i] = False
                visited[j[0]] = False
                visited[j[1]] = False
                add += solve_simple_nav_polygons(polygons, len(used))
                break

        return add

    return num_triangles(0, 0) % int(1e9 + 7)


