def f(generators, restrictions, x):
    max_output = 0
    for i in range(len(generators) - 1):
        ui, vi, di = restrictions[i]
        generator_i = (generators[ui]*x**2 + generators[ui-1]*x + generators[ui-2]).diff(x)
        generator_v = (generators[vi]*x**2 + generators[vi-1]*x + generators[vi-2]).diff(x)
        span = generator_v - generator_i
        span_end = xmax(span) + di
        if span_end > -1.0e-10:
            max_output = max(max_output, generators[ui - 1] * span_end**2 + (generators[ui - 2] + generators[ui - 1]) * span_end + generators[ui - 2])
    return max_output

def xmax(span):
    return span.limit(process=True).xlimit(min=True).limit(process=True)
