                cost = dfs(neighbor, d + graph[u][neighbor], d + path_cost)
                if cost not in distances:
                    distances[cost] = {'count': 1, 'path': [u, neighbor]}
                else:
                    distances[cost]['count'] += 1
                    distances[cost]['path'].append(neighbor)
        return 0

