def min_roads(N, A):
    N = len(A)
    dp = [0] * (N + 1)
    parent = [i for i in range(N+1)]
    graph = [[] for _ in range(N+1)]

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(a, b):
        pa, pb = find(a), find(b)
        if pa != pb:
            parent[max(pa, pb)] = min(pa, pb)
            graph[max(pa, pb)].extend(graph[pb])

    for i in range(1, N + 1):
        for j in range(i + 1, N + 1):
            if (A[i-1] & A[j-1]) > 0:
                union(i, j)
                graph[i].append(j)
                graph[j].append(i)

    ans = N
    for i in range(1, N + 1):
        if find(i) != i:
            ans -= 1
        dp[find(i)] += len(graph[i]) * min(A[i-1], A[find(i)-1])

    return ans if ans > 0 else -1

