import heapq

def find_smallest_broom(n, edges):
    # Initialize parent and size arrays
    parent = list(range(n + 1))
    size = [1] * (n + 1)

    def find_set(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    # Union-Find to merge sets
    def union(x, y, x_char, y_char, x_size, y_size):
        x_set = find_set(x)
        y_set = find_set(y)
        if x_set != y_set:
            if x_size > y_size:
                parent[y_set] = x_set
                y_size = size[y_set]
            else:
                parent[x_set] = y_set
                x_size = size[x_set]
            merged = (x_size + y_size) // 2
            root = find_size()
            if root > merged or size[root] + size[x_set] + size[y_set] <= n:
                return merged
            else:
                return float('inf')

    def find_size():
        root = find_set(1)
        total_size = size[1]
        while parent[root] != root:
            root = parent[root]
            total_size += size[root]
        return total_size

    # Union each pair of edges
    for u, v, char in edges:
        if u != 1 and v != 1 and union(u, v, char, char, size[u], size[v]):
            return float('inf')

    # Find the minimum possible size of the broom after simplification
    p, minimized_size = float('inf'), float('inf')
    for j in range(2, len(edges) + 1):
        for i in range(len(edges)):
            if (edges[i][0], edges[i][1], edges[i][2]) == (1, j, ' ') and (edges[i-1][0], edges[i-1][1], edges[i-1][2]) == (1, j - 1, ' '):
                minimized_size = min(minimized_size, j - 1)
                p = max(p, j - 1)
                break

    return minimized_size, p

